  1	use crate::device::{BufferAccess, RuntimeArgCategory, RuntimeArgInfo};
  2	use crate::env_bool;
  3	use crate::instance::{Instance, Simulator};
  4	use std::ffi::{CStr, CString};
  5	use std::os::raw::{c_char, c_int};
  6	use std::path::Path;
  7	use std::sync::Mutex;
  8	
  9	struct FrtInstanceHandle {
 10	    instance: Instance,
 11	    args_cache: Vec<RuntimeArgInfo>,
 12	    arg_name_cache: Option<CString>,
 13	    arg_type_cache: Option<CString>,
 14	}
 15	
 16	/// Obtain a shared reference to the `FrtInstanceHandle` behind an opaque pointer.
 17	///
 18	/// Returns `None` (and sets the last-error message) when `handle` is null.
 19	fn with_handle_ref(handle: *const std::ffi::c_void) -> Option<&'static FrtInstanceHandle> {
 20	    if handle.is_null() {
 21	        set_last_error("handle is null");
 22	        return None;
 23	    }
 24	    // SAFETY: handle was created by frt_instance_open via Box::into_raw, and
 25	    // the caller guarantees the pointer remains valid for the duration of
 26	    // this call.
 27	    Some(unsafe { &*handle.cast::<FrtInstanceHandle>() })
 28	}
 29	
 30	/// Obtain an exclusive reference to the `FrtInstanceHandle` behind an opaque pointer.
 31	///
 32	/// Returns `None` (and sets the last-error message) when `handle` is null.
 33	fn with_handle_mut(handle: *mut std::ffi::c_void) -> Option<&'static mut FrtInstanceHandle> {
 34	    if handle.is_null() {
 35	        set_last_error("handle is null");
 36	        return None;
 37	    }
 38	    // SAFETY: handle was created by frt_instance_open via Box::into_raw, and
 39	    // the caller guarantees exclusive access for the duration of this call.
 40	    Some(unsafe { &mut *handle.cast::<FrtInstanceHandle>() })
 41	}
 42	
 43	static LAST_ERROR: Mutex<Option<CString>> = Mutex::new(None);
 44	
 45	fn set_last_error(msg: impl Into<String>) {
 46	    let mut text = msg.into();
 47	    if text.contains('\0') {
 48	        text = text.replace('\0', " ");
 49	    }
 50	    if let Ok(mut guard) = LAST_ERROR.lock() {
 51	        *guard = CString::new(text).ok();
 52	    }
 53	}
 54	
 55	fn clear_last_error() {
 56	    if let Ok(mut guard) = LAST_ERROR.lock() {
 57	        *guard = None;
 58	    }
 59	}
 60	
 61	fn to_str<'a>(ptr: *const c_char, field: &str) -> Result<Option<&'a str>, String> {
 62	    if ptr.is_null() {
 63	        return Ok(None);
 64	    }
 65	    // SAFETY: ptr is non-null (checked above) and the caller guarantees it
 66	    // points to a valid NUL-terminated C string.
 67	    let c = unsafe { CStr::from_ptr(ptr) };
 68	    c.to_str()
 69	        .map(Some)
 70	        .map_err(|e| format!("invalid utf-8 in {field}: {e}"))
 71	}
 72	
 73	fn parse_simulator(sim: Option<&str>) -> Simulator {
