  6	use frt_cosim::runner::verilator::VerilatorRunner;
  7	use frt_cosim::runner::xsim::XsimRunner;
  8	use frt_cosim::runner::SimRunner;
  9	use std::collections::HashMap;
 10	use std::path::{Path, PathBuf};
 11	use std::process::Child;
 12	use std::process::Command;
 13	use std::time::Instant;
 14	
 15	enum TbDir {
 16	    Temp(tempfile::TempDir),
 17	    Fixed(PathBuf),
 18	}
 19	
 20	impl TbDir {
 21	    fn path(&self) -> &Path {
 22	        match self {
 23	            Self::Temp(d) => d.path(),
 24	            Self::Fixed(p) => p.as_path(),
 25	        }
 26	    }
 27	}
 28	
 29	struct RuntimeOptions {
 30	    start_gui: bool,
 31	    save_waveform: bool,
 32	    setup_only: bool,
 33	    resume_from_post_sim: bool,
 34	    work_dir: Option<PathBuf>,
 35	    work_dir_parallel: bool,
 36	    part_num_override: Option<String>,
 37	}
 38	
 39	struct BufferBinding {
 40	    ptr: *mut u8,
 41	    bytes: usize,
 42	    access: BufferAccess,
 43	    load_suspended: bool,
 44	    store_suspended: bool,
 45	}
 46	
 47	struct RunningSimulation {
 48	    child: Child,
 49	    started_at: Instant,
 50	    paused: bool,
 51	}
 52	
 53	enum SimulationState {
 54	    Idle,
 55	    Running(RunningSimulation),
 56	    Finished,
 57	}
 58	
 59	pub struct CosimDevice {
 60	    spec: KernelSpec,
 61	    arg_names: HashMap<u32, String>,
 62	    stream_arg_names: HashMap<u32, String>,
 63	    ctx: CosimContext,
 64	    runner: Box<dyn SimRunner>,
 65	    tb_dir: TbDir,
 66	    _extract_dir: tempfile::TempDir,
 67	    setup_only: bool,
 68	    resume_from_post_sim: bool,
 69	    scalars: HashMap<u32, Vec<u8>>,
 70	    pending_buffers: HashMap<u32, BufferBinding>,
 71	    simulation_state: SimulationState,
 72	    readback_scheduled: bool,
 73	    pending_sim_error: Option<FrtError>,
 74	    load_ns: u64,
 75	    compute_ns: u64,
 76	    store_ns: u64,
 77	}
 78	
 79	// SAFETY: CosimDevice is only accessed from a single owner thread.
 80	// The raw `*mut u8` pointers in BufferBinding point to host memory whose
 81	// lifetime is managed by the caller (the C++ compatibility layer) and
 82	// outlives the device.
 83	unsafe impl Send for CosimDevice {}
 84	
 85	impl CosimDevice {
 86	    pub fn open(path: &Path, sim: &Simulator) -> Result<Self> {
 87	        let (spec, extract_dir) = frt_cosim::metadata::load_spec(path)?;
 88	        let arg_names = spec
 89	            .args
 90	            .iter()
 91	            .map(|arg| (arg.id, arg.name.clone()))
 92	            .collect();
 93	        let stream_arg_names = spec
 94	            .args
 95	            .iter()
 96	            .filter_map(|arg| match arg.kind {
 97	                frt_cosim::metadata::ArgKind::Stream { .. } => Some((arg.id, arg.name.clone())),
 98	                frt_cosim::metadata::ArgKind::Scalar { .. }
 99	                | frt_cosim::metadata::ArgKind::Mmap { .. } => None,
100	            })
101	            .collect();
102	        let opts = runtime_options();
103	        let tb_dir = make_tb_dir(opts.work_dir.as_deref(), opts.work_dir_parallel)?;
104	        let ctx = if opts.resume_from_post_sim {
105	            let config_path = tb_dir.path().join("dpi_config.json");
106	            let json = std::fs::read_to_string(&config_path).map_err(|e| {
107	                FrtError::MetadataParse(format!("failed to read {}: {e}", config_path.display()))
108	            })?;
109	            CosimContext::open_from_config(&spec, &json)?
110	        } else {
111	            CosimContext::new(&spec)?
112	        };
113	
114	        let runner: Box<dyn SimRunner> = match sim {
115	            Simulator::Verilator => {
116	                let dpi = dpi_lib_path("verilator")?;
117	                Box::new(VerilatorRunner::find(dpi)?)
118	            }
119	            Simulator::Xsim { legacy } => {
120	                let dpi = dpi_lib_path("xsim")?;
121	                Box::new(XsimRunner::find(
122	                    dpi,
123	                    *legacy || env_bool(frt_shm::env::FRT_XSIM_LEGACY),
124	                    opts.save_waveform,
125	                    opts.start_gui,
126	                    opts.part_num_override.clone(),
127	                )?)
128	            }
129	        };
130	
131	        Ok(Self {
132	            spec,
133	            arg_names,
134	            stream_arg_names,
135	            ctx,
136	            runner,
137	            tb_dir,
138	            _extract_dir: extract_dir,
139	            setup_only: opts.setup_only,
140	            resume_from_post_sim: opts.resume_from_post_sim,
141	            scalars: HashMap::new(),
142	            pending_buffers: HashMap::new(),
143	            simulation_state: SimulationState::Idle,
144	            readback_scheduled: false,
145	            pending_sim_error: None,
146	            load_ns: 0,
147	            compute_ns: 0,
148	            store_ns: 0,
149	        })
150	    }
151	
152	    fn spawn_noop_process() -> Result<Child> {
153	        let mut cmd = Command::new("/bin/sh");
154	        cmd.args(["-c", ":"]);
155	        frt_cosim::runner::configure_sim_command(&mut cmd);
156	        Ok(cmd.spawn()?)
157	    }
158	
159	    fn copy_back_to_host(&mut self) -> Result<()> {
160	        let started = Instant::now();
161	        for (index, binding) in &self.pending_buffers {
162	            if !binding.access.stores_to_host() || binding.store_suspended {
163	                continue;
164	            }
165	            if binding.ptr.is_null() && binding.bytes != 0 {
166	                return Err(FrtError::MetadataParse(format!(
167	                    "null pointer for buffer arg {index}"
168	                )));
169	            }
170	            let name = self.arg_name(*index)?.to_owned();
171	            if let Some(seg) = self.ctx.buffers.get(&name) {
172	                let len = binding.bytes.min(seg.len());
173	                if len > 0 {
174	                    // SAFETY: binding.ptr is non-null (checked above) and
175	                    // len <= binding.bytes, so the slice is within the
176	                    // caller-provided host buffer.
177	                    let dst = unsafe { std::slice::from_raw_parts_mut(binding.ptr, len) };
178	                    dst.copy_from_slice(&seg.as_slice()[..len]);
179	                }
180	            }
181	        }
182	        self.store_ns = started.elapsed().as_nanos() as u64;
183	        // Ensure non-zero to signal "copy-back completed" (callers use
184	        // store_ns() == 0 to mean "not yet run").
185	        if self.store_ns == 0 {
186	            self.store_ns = 1;
187	        }
188	        Ok(())
189	    }
190	
191	    fn arg_name(&self, index: u32) -> Result<&str> {
192	        self.arg_names
193	            .get(&index)
194	            .map(String::as_str)
195	            .ok_or_else(|| FrtError::MetadataParse(format!("no arg at index {index}")))
196	    }
197	
198	    fn stream_arg_name(&self, index: u32) -> Result<&str> {
199	        self.stream_arg_names
200	            .get(&index)
201	            .map(String::as_str)
202	            .ok_or_else(|| FrtError::MetadataParse(format!("no stream arg at index {index}")))
203	    }
204	
205	    fn poll_simulation(&mut self) -> Result<bool> {
206	        match &mut self.simulation_state {
207	            SimulationState::Idle => Ok(false),
208	            SimulationState::Finished => Ok(true),
209	            SimulationState::Running(run) => {
210	                let maybe_status = run.child.try_wait()?;
211	                if let Some(status) = maybe_status {
212	                    self.compute_ns = run.started_at.elapsed().as_nanos() as u64;
213	                    if !status.success() {
214	                        self.pending_sim_error = Some(FrtError::SimFailed(status));
215	                    }
216	                    self.simulation_state = SimulationState::Finished;
217	                    Ok(true)
218	                } else {
219	                    Ok(false)
220	                }
221	            }
222	        }
223	    }
224	
225	    fn wait_simulation(&mut self) -> Result<()> {
226	        if let SimulationState::Running(run) = &mut self.simulation_state {
227	            let status = run.child.wait()?;
