159	    fn copy_back_to_host(&mut self) -> Result<()> {
160	        let started = Instant::now();
161	        for (index, binding) in &self.pending_buffers {
162	            if !binding.access.stores_to_host() || binding.store_suspended {
163	                continue;
164	            }
165	            if binding.ptr.is_null() && binding.bytes != 0 {
166	                return Err(FrtError::MetadataParse(format!(
167	                    "null pointer for buffer arg {index}"
168	                )));
169	            }
170	            let name = self.arg_name(*index)?.to_owned();
171	            if let Some(seg) = self.ctx.buffers.get(&name) {
172	                let len = binding.bytes.min(seg.len());
173	                if len > 0 {
174	                    // SAFETY: binding.ptr is non-null (checked above) and
175	                    // len <= binding.bytes, so the slice is within the
176	                    // caller-provided host buffer.
177	                    let dst = unsafe { std::slice::from_raw_parts_mut(binding.ptr, len) };
178	                    dst.copy_from_slice(&seg.as_slice()[..len]);
