297	        part_num_override: env_non_empty(env::FRT_XSIM_PART_NUM),
298	    }
299	}
300	
301	fn make_tb_dir(work_dir: Option<&Path>, parallel: bool) -> Result<TbDir> {
302	    if let Some(base) = work_dir {
303	        std::fs::create_dir_all(base)?;
304	        if parallel {
305	            let suffix = format!(
306	                "{}_{}",
307	                std::process::id(),
308	                std::time::SystemTime::now()
309	                    .duration_since(std::time::UNIX_EPOCH)
310	                    .unwrap_or_default()
311	                    .as_nanos()
312	            );
313	            let dir = base.join(suffix);
314	            std::fs::create_dir_all(&dir)?;
315	            return Ok(TbDir::Fixed(dir));
316	        }
317	        return Ok(TbDir::Fixed(base.to_path_buf()));
318	    }
319	    Ok(TbDir::Temp(tempfile::tempdir()?))
320	}
321	
322	fn dpi_lib_path(variant: &str) -> Result<PathBuf> {
323	    // Prefer searching relative to libfrt.so itself (covers staging tests
324	    // where the host binary is compiled into /tmp but libfrt.so lives in
325	    // the install prefix). With FRT linked statically, dladdr resolves to
326	    // the host executable instead, so the install prefix is located via
327	    // TAPA_HOME (see `dpi_lib_path_from_exe`).
328	    let self_path = self_lib_path().unwrap_or_else(|| std::env::current_exe().unwrap_or_default());
329	    dpi_lib_path_from_exe(&self_path, variant)
330	}
331	
332	#[cfg(unix)]
333	fn self_lib_path() -> Option<PathBuf> {
334	    // Use dladdr to find the path of the shared library containing this function.
335	    #[allow(
336	        clippy::fn_to_numeric_cast_any,
337	        reason = "dladdr requires a function address as *const c_void"
338	    )]
339	    let ptr = self_lib_path as *const ();
340	    // SAFETY: zeroed is valid for Dl_info (it is a plain-old-data C struct).
341	    let mut info: libc::Dl_info = unsafe { std::mem::zeroed() };
342	    // SAFETY: dladdr resolves the shared-object path for a given address.
343	    // `ptr` is a valid function pointer in the current image.
344	    if unsafe { libc::dladdr(ptr.cast(), &raw mut info) } != 0 && !info.dli_fname.is_null() {
345	        // SAFETY: dli_fname is non-null (checked above) and points to a
346	        // NUL-terminated string managed by the dynamic linker.
347	        let path = unsafe { std::ffi::CStr::from_ptr(info.dli_fname) };
348	        path.to_str().ok().map(PathBuf::from)
349	    } else {
350	        None
351	    }
352	}
353	
354	#[cfg(not(unix))]
355	fn self_lib_path() -> Option<PathBuf> {
356	    None
357	}
358	
359	fn dpi_lib_path_from_exe(exe: &Path, variant: &str) -> Result<PathBuf> {
360	    let mut search_dirs = Vec::new();
361	    if let Some(dir) = exe.parent() {
362	        search_dirs.push(dir.to_path_buf());
363	        // Installed layout: bin/ is sibling of lib/
364	        if let Some(parent) = dir.parent() {
365	            search_dirs.push(parent.join("lib"));
366	        }
367	        for ancestor in dir.ancestors() {
368	            search_dirs.push(ancestor.to_path_buf());
369	            search_dirs.push(ancestor.join("fpga-runtime/cargo"));
370	            search_dirs.push(ancestor.join("cargo"));
371	        }
372	    }
373	    // Installed layout with statically linked FRT: the libraries live under
374	    // the TAPA package root advertised via TAPA_HOME (this is the layout the
375	    // staging tests exercise after `install.sh`).
376	    if let Ok(home) = std::env::var("TAPA_HOME") {
377	        let home = PathBuf::from(home);
378	        search_dirs.push(home.join("usr/lib"));
379	        search_dirs.push(home.join("lib"));
380	    }
381	    // Also search LD_LIBRARY_PATH (covers staging tests that copy binaries)
382	    if let Ok(ldpath) = std::env::var("LD_LIBRARY_PATH") {
383	        for dir in ldpath.split(':') {
384	            if !dir.is_empty() {
385	                search_dirs.push(PathBuf::from(dir));
386	            }
387	        }
388	    }
389	    let candidates = dpi_library_candidates(variant);
390	    for candidate in candidates {
391	        for base in &search_dirs {
392	            let p = base.join(&candidate);
393	            if p.exists() {
394	                // Downstream cosim tools run from deep temp/obj subdirectories:
395	                // Verilator's `c++` link from `obj_dir` and XSIM's `-sv_root`
396	                // (derived from this path's parent) both resolve relative to
397	                // their own CWD, not ours. A path resolved relative to the test
398	                // CWD is unusable there, so return an absolute path.
399	                return Ok(std::fs::canonicalize(&p).unwrap_or(p));
400	            }
401	        }
402	    }
403	    Err(FrtError::MetadataParse(format!(
404	        "libfrt_dpi_{variant} shared library not found next to executable, \
405	         under TAPA_HOME, or on LD_LIBRARY_PATH"
406	    )))
407	}
408	
409	fn dpi_library_candidates(variant: &str) -> [String; 2] {
410	    let native = format!(
411	        "{}frt_dpi_{variant}{}",
412	        std::env::consts::DLL_PREFIX,
413	        std::env::consts::DLL_SUFFIX,
414	    );
415	    let fallback_suffix = if std::env::consts::DLL_SUFFIX == ".so" {
416	        ".dylib"
417	    } else {
418	        ".so"
419	    };
420	    [native, format!("libfrt_dpi_{variant}{fallback_suffix}")]
421	}
422	
423	impl Device for CosimDevice {
424	    fn set_scalar_arg(&mut self, index: u32, value: &[u8]) -> Result<()> {
425	        self.scalars.insert(index, value.to_vec());
426	        Ok(())
427	    }
428	
429	    fn set_buffer_arg(
430	        &mut self,
431	        index: u32,
432	        ptr: *mut u8,
433	        bytes: usize,
434	        access: BufferAccess,
435	    ) -> Result<()> {
436	        let name = self.arg_name(index)?.to_owned();
437	        if !self.ctx.buffers.contains_key(&name) {
438	            return Err(FrtError::MetadataParse(format!(
439	                "arg '{name}' is not an mmap buffer"
440	            )));
441	        }
442	        self.ctx.resize_buffer(&name, bytes)?;
443	        self.pending_buffers.insert(
444	            index,
445	            BufferBinding {
446	                ptr,
447	                bytes,
448	                access,
449	                load_suspended: false,
450	                store_suspended: false,
451	            },
452	        );
453	        Ok(())
454	    }
455	
456	    fn set_stream_arg(&mut self, index: u32, shm_path: &str) -> Result<()> {
457	        if shm_path.is_empty() {
458	            return Ok(());
459	        }
460	        let name = match self.stream_arg_name(index) {
461	            Ok(n) => n.to_owned(),
462	            Err(_) if self.resume_from_post_sim => return Ok(()),
463	            Err(e) => return Err(e),
464	        };
465	        // In resume mode the context has no streams; skip binding.
466	        if self.ctx.streams.contains_key(&name) {
467	            self.ctx.bind_stream_path(&name, shm_path)?;
468	        }
469	        Ok(())
470	    }
471	
472	    fn suspend_buffer(&mut self, index: u32) -> usize {
473	        let Some(binding) = self.pending_buffers.get_mut(&index) else {
474	            return 0;
475	        };
476	        let mut erased = 0;
477	        if binding.access.loads_from_host() && !binding.load_suspended {
478	            binding.load_suspended = true;
479	            erased += 1;
480	        }
481	        if binding.access.stores_to_host() && !binding.store_suspended {
482	            binding.store_suspended = true;
483	            erased += 1;
484	        }
485	        erased
486	    }
487	
488	    fn write_to_device(&mut self) -> Result<()> {
489	        let started = Instant::now();
490	        for (index, binding) in &self.pending_buffers {
491	            if !binding.access.loads_from_host() || binding.load_suspended {
492	                continue;
493	            }
494	            if binding.ptr.is_null() && binding.bytes != 0 {
495	                return Err(FrtError::MetadataParse(format!(
496	                    "null pointer for buffer arg {index}"
497	                )));
498	            }
499	            let name = self.arg_name(*index)?.to_owned();
500	            if let Some(seg) = self.ctx.buffers.get_mut(&name) {
501	                let len = binding.bytes.min(seg.len());
502	                if len > 0 {
503	                    // SAFETY: binding.ptr is non-null (checked above) and
504	                    // len <= binding.bytes, so the slice is within the
505	                    // caller-provided host buffer.
506	                    let src = unsafe { std::slice::from_raw_parts(binding.ptr, len) };
507	                    seg.as_mut_slice()[..len].copy_from_slice(src);
508	                }
509	            }
510	        }
511	        self.load_ns = started.elapsed().as_nanos() as u64;
512	        Ok(())
513	    }
514	
515	    fn read_from_device(&mut self) -> Result<()> {
516	        if matches!(self.simulation_state, SimulationState::Running(_)) {
517	            self.readback_scheduled = true;
518	            return Ok(());
519	        }
520	        self.copy_back_to_host()?;

