 5	use crate::{
 6	    context::CosimContext,
 7	    error::{CosimError, Result},
 8	    metadata::KernelSpec,
 9	};
10	use std::collections::HashMap;
11	#[cfg(unix)]
12	use std::os::unix::process::CommandExt;
13	use std::path::Path;
14	use std::process::Child;
15	use std::process::Command;
16	
17	pub struct SimResult {
18	    pub wall_ns: u64,
19	}
20	
21	pub trait SimRunner {
22	    fn prepare(
23	        &self,
24	        spec: &KernelSpec,
25	        ctx: &CosimContext,
26	        scalar_values: &HashMap<u32, Vec<u8>>,
27	        tb_dir: &Path,
28	    ) -> Result<()>;
29	    fn spawn(&self, spec: &KernelSpec, ctx: &CosimContext, tb_dir: &Path) -> Result<Child>;
30	
31	    fn run(&self, spec: &KernelSpec, ctx: &CosimContext, tb_dir: &Path) -> Result<SimResult> {
32	        let t0 = std::time::Instant::now();
33	        self.prepare(spec, ctx, &HashMap::new(), tb_dir)?;
34	        let mut child = self.spawn(spec, ctx, tb_dir)?;
35	        let status = child.wait()?;
36	        let wall_ns = t0.elapsed().as_nanos() as u64;
37	        if !status.success() {
38	            return Err(CosimError::SimFailed(status));
39	        }
40	        Ok(SimResult { wall_ns })
41	    }
42	}
43	
44	/// Acquire an exclusive `flock`-based lock on the given path.
45	///
46	/// Creates the file (and parent directories) if they don't exist.
47	/// Returns the open `File` whose lifetime holds the lock.
48	#[cfg(unix)]
49	pub fn acquire_exclusive_lock(lock_path: &std::path::Path) -> Result<std::fs::File> {
50	    use std::os::fd::AsRawFd;
51	    if let Some(parent) = lock_path.parent() {
52	        std::fs::create_dir_all(parent)?;
53	    }
54	    let file = std::fs::OpenOptions::new()
55	        .create(true)
56	        .truncate(false)
57	        .read(true)
58	        .write(true)
59	        .open(lock_path)?;
60	    // SAFETY: `file` is an open file we just created/opened, so `as_raw_fd()` is a valid fd.
61	    // `flock(fd, LOCK_EX)` is safe to call on any valid file descriptor.
62	    if unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX) } != 0 {
63	        return Err(std::io::Error::last_os_error().into());
64	    }
65	    Ok(file)
66	}
67	
68	pub fn configure_sim_command(cmd: &mut Command) {
69	    #[cfg(unix)]
70	    // SAFETY: The `pre_exec` closure runs between `fork()` and `exec()` in the child
71	    // process. It only calls `setpgid(0, 0)` which is async-signal-safe per POSIX
72	    // and does not access any shared mutable state.
73	    unsafe {
74	        cmd.pre_exec(|| {
75	            #[allow(
76	                unused_unsafe,
77	                reason = "inner unsafe needed for multiple_unsafe_ops_per_block"
78	            )]
79	            // SAFETY: `setpgid(0, 0)` is async-signal-safe and only affects
80	            // the freshly-forked child process.
81	            if unsafe { libc::setpgid(0, 0) } != 0 {
82	                return Err(std::io::Error::last_os_error());
83	            }
84	            Ok(())
85	        });
86	    }
87	}

