70	    // SAFETY: The `pre_exec` closure runs between `fork()` and `exec()` in the child
71	    // process. It only calls `setpgid(0, 0)` which is async-signal-safe per POSIX
72	    // and does not access any shared mutable state.
73	    unsafe {
74	        cmd.pre_exec(|| {
75	            #[allow(
76	                unused_unsafe,
77	                reason = "inner unsafe needed for multiple_unsafe_ops_per_block"
78	            )]
79	            // SAFETY: `setpgid(0, 0)` is async-signal-safe and only affects
80	            // the freshly-forked child process.
81	            if unsafe { libc::setpgid(0, 0) } != 0 {
82	                return Err(std::io::Error::last_os_error());
83	            }
84	            Ok(())
85	        });
86	    }
87	}

