 16	    pub start_gui: bool,
 17	    pub part_num_override: Option<String>,
 18	}
 19	
 20	impl XsimRunner {
 21	    pub fn find(
 22	        dpi_lib: PathBuf,
 23	        legacy: bool,
 24	        save_waveform: bool,
 25	        start_gui: bool,
 26	        part_num_override: Option<String>,
 27	    ) -> Result<Self> {
 28	        Ok(Self {
 29	            dpi_lib,
 30	            legacy,
 31	            save_waveform,
 32	            start_gui,
 33	            part_num_override,
 34	        })
 35	    }
 36	}
 37	
 38	impl SimRunner for XsimRunner {
 39	    fn prepare(
 40	        &self,
 41	        spec: &KernelSpec,
 42	        ctx: &CosimContext,
 43	        scalar_values: &HashMap<u32, Vec<u8>>,
 44	        tb_dir: &Path,
 45	    ) -> Result<()> {
 46	        let part = self
 47	            .part_num_override
 48	            .as_deref()
 49	            .or(spec.part_num.as_deref())
 50	            .unwrap_or("xc7a100tcsg324-1");
 51	        apply_default_nettype_wire(spec)?;
 52	        let generator = XsimTbGenerator::new(
 53	            spec,
 54	            &self.dpi_lib,
 55	            &ctx.base_addresses,
 56	            scalar_values,
 57	            part,
 58	            self.save_waveform,
 59	            self.legacy,
 60	        );
 61	        let tb_file = format!("tb_{}.sv", spec.top_name);
 62	
 63	        std::fs::write(tb_dir.join(&tb_file), generator.render_tb()?)?;
 64	        std::fs::write(tb_dir.join("run_cosim.tcl"), generator.render_tcl(tb_dir)?)?;
 65	        Ok(())
 66	    }
 67	
 68	    fn spawn(
 69	        &self,
 70	        _spec: &KernelSpec,
 71	        ctx: &CosimContext,
 72	        tb_dir: &Path,
 73	    ) -> Result<std::process::Child> {
 74	        let mode = if self.start_gui { "gui" } else { "batch" };
 75	        let home = tb_dir.join("run");
 76	        std::fs::create_dir_all(&home)?;
 77	        let vivado_bin = which("vivado").map_err(|_e| CosimError::ToolNotFound("vivado".into()))?;
 78	        let mut cmd = Command::new(vivado_bin);
 79	        // Base environment (incl. Xilinx tool paths) FIRST, then per-instance
 80	        // overrides LAST — .envs() would overwrite .env() values for keys
 81	        // already in the parent env (HOME, TMPDIR).
 82	        cmd.args(["-mode", mode, "-source", "run_cosim.tcl"])
 83	            .current_dir(tb_dir)
 84	            .envs(xilinx_environ())
 85	            .env("HOME", home.as_os_str())
 86	            .env("TMPDIR", home.as_os_str())
 87	            .env(frt_shm::env::TAPA_DPI_CONFIG, ctx.dpi_config_json());
 88	        configure_sim_command(&mut cmd);
 89	        let child = cmd.spawn()?;
 90	        Ok(child)
 91	    }
 92	}
 93	
 94	fn apply_default_nettype_wire(spec: &KernelSpec) -> Result<()> {
 95	    const PREFIX: &[u8] = b"`default_nettype";
 96	    for file in &spec.verilog_files {
 97	        let Some(ext) = file.extension().and_then(|e| e.to_str()) else {
 98	            continue;
 99	        };
100	        if !matches!(ext, "v" | "sv") {
101	            continue;
102	        }
103	        // Read only enough bytes to check for the prefix, avoiding a full
104	        // read_to_string when the directive is already present.
105	        {
106	            let mut f = std::fs::File::open(file)?;
107	            let mut buf = [0u8; PREFIX.len()];
108	            if f.read(&mut buf)? == PREFIX.len() && buf == *PREFIX {
109	                continue;
110	            }
111	        }
112	        let content = std::fs::read_to_string(file)?;
113	        std::fs::write(file, format!("`default_nettype wire\n{content}"))?;
114	    }
115	    Ok(())
116	}

