233	    for (i, chunk) in bytes.chunks(4).enumerate() {
234	        let mut raw = [0u8; 4];
235	        raw[..chunk.len()].copy_from_slice(chunk);
236	        words.push(ScalarWord {
237	            reg_offset: base_offset + (i as u32) * 4,
238	            value_u32: u32::from_le_bytes(raw),
239	        });
240	    }
241	    if words.is_empty() {
242	        words.push(ScalarWord {
243	            reg_offset: base_offset,
244	            value_u32: 0,
245	        });
246	    }
247	    words
248	}

