 15	/// Look up the register offset for an arg name in the scalar register map.
 16	/// Falls back to `"{name}_offset"` if the exact name is not found.
 17	pub fn lookup_register_offset(spec: &KernelSpec, name: &str) -> u32 {
 18	    spec.scalar_register_map
 19	        .get(name)
 20	        .or_else(|| {
 21	            let key = format!("{name}_offset");
 22	            spec.scalar_register_map.get(&key)
 23	        })
 24	        .copied()
 25	        .unwrap_or(0)
 26	}
