 28	/// Read all Verilog file contents for peek-port detection and similar scans.
 29	pub fn read_verilog_contents(spec: &KernelSpec) -> Vec<String> {
 30	    spec.verilog_files
 31	        .iter()
 32	        .filter_map(|f| std::fs::read_to_string(f).ok())
 33	        .collect()
 34	}
