 36	/// Classify spec args into four groups by applying backend-specific constructors.
 37	#[allow(
 38	    clippy::implicit_hasher,
 39	    reason = "generic hasher adds no value for internal helper"
 40	)]
 41	pub fn classify_args<M, S, T>(
 42	    spec: &KernelSpec,
 43	    scalar_values: &HashMap<u32, Vec<u8>>,
 44	    verilog_contents: &[String],
 45	    make_mmap: impl Fn(&crate::metadata::ArgSpec, u32) -> M,
 46	    make_scalar: impl Fn(&crate::metadata::ArgSpec, u32, u32, &[u8]) -> S,
 47	    make_stream: impl Fn(&crate::metadata::ArgSpec, usize, Option<String>, bool) -> T,
 48	) -> (Vec<M>, Vec<S>, Vec<T>, Vec<T>) {
 49	    use crate::metadata::{ArgKind, Mode, StreamDir, StreamProtocol};
 50	    use names::{infer_peek_name, stream_peek_ports_exist};
 51	
 52	    let mut mmaps = vec![];
 53	    let mut scalars = vec![];
 54	    let mut streams_in = vec![];
 55	    let mut streams_out = vec![];
 56	
 57	    for arg in &spec.args {
 58	        match &arg.kind {
 59	            ArgKind::Mmap { .. } => {
 60	                let offset = lookup_register_offset(spec, &arg.name);
 61	                mmaps.push(make_mmap(arg, offset));
 62	            }
 63	            ArgKind::Scalar { width } => {
 64	                let offset = lookup_register_offset(spec, &arg.name);
 65	                let bytes =
 66	                    normalized_scalar_bytes(*width, scalar_values.get(&arg.id).map(Vec::as_slice));
 67	                scalars.push(make_scalar(arg, *width, offset, &bytes));
 68	            }
 69	            ArgKind::Stream {
 70	                width,
 71	                dir,
 72	                protocol,
 73	                ..
 74	            } => {
 75	                let w = (*width as usize).div_ceil(8);
 76	                let axis = *protocol == StreamProtocol::Axis;
 77	                let peek = if spec.mode == Mode::Hls && *dir == StreamDir::In {
 78	                    infer_peek_name(&arg.name).filter(|cand| {
 79	                        stream_peek_ports_exist(verilog_contents, &spec.top_name, cand)
 80	                    })
 81	                } else {
 82	                    None
 83	                };
 84	                let s = make_stream(arg, w, peek, axis);
 85	                match dir {
 86	                    StreamDir::In => streams_in.push(s),
 87	                    StreamDir::Out => streams_out.push(s),
 88	                }
 89	            }
 90	        }
 91	    }
 92	    (mmaps, scalars, streams_in, streams_out)
 93	}
 94	
 95	pub fn normalized_scalar_bytes(width_bits: u32, raw: Option<&[u8]>) -> Vec<u8> {
 96	    let expected = (width_bits as usize).div_ceil(8).max(1);
 97	    let mut out = raw.map(<[u8]>::to_vec).unwrap_or_default();
 98	    if out.len() < expected {
 99	        out.resize(expected, 0);
100	    } else if out.len() > expected {
101	        out.truncate(expected);
102	    }
103	    out
104	}
