 25	reg [7:0] s_axi_control_AWADDR = 0;
 26	reg s_axi_control_WVALID = 0;
 27	wire s_axi_control_WREADY;
 28	reg [31:0] s_axi_control_WDATA = 0;
 29	reg [3:0] s_axi_control_WSTRB = 0;
 30	reg s_axi_control_ARVALID = 0;
 31	wire s_axi_control_ARREADY;
 32	reg [7:0] s_axi_control_ARADDR = 0;
