 6	    // Vitis HLS 2020.x: `localparam ADDR_A_0 = 6'h10`
 7	    // Vitis HLS 2021+:  `localparam ADDR_A_DATA_0 = 6'h10`
 8	    // Non-greedy capture ensures `_data_0` suffix is consumed, not part of name.
 9	    let re = regex_lite::Regex::new(
10	        r"(?i)localparam\s+addr_(\w+?)_(?:data_)?0\s*=\s*[\d']*h([0-9a-fA-F]+)",
11	    )
