  1	use super::{ArgKind, ArgSpec, KernelSpec, Mode, StreamDir, StreamProtocol};
  2	use crate::error::{CosimError, Result};
  3	use quick_xml::events::Event;
  4	use quick_xml::Reader;
  5	use std::collections::HashMap;
  6	use std::path::Path;
  7	
  8	pub fn parse_kernel_xml(xml: &str, _verilog_dir: &Path) -> Result<KernelSpec> {
  9	    let mut reader = Reader::from_str(xml);
 10	    reader.config_mut().trim_text(true);
 11	    let mut top_name = String::new();
 12	    let mut args = Vec::new();
 13	    let mut buf = Vec::new();
 14	    // Map from port name to (mode, dataWidth) parsed from <port> elements.
 15	    // For TAPA-generated kernel.xml, <ports> precedes <args>, so this is
 16	    // populated before we process any <arg> elements in a single SAX pass.
 17	    let mut port_info: HashMap<String, (String, u32)> = HashMap::new();
 18	
 19	    loop {
 20	        match reader.read_event_into(&mut buf) {
 21	            Ok(Event::Start(e) | Event::Empty(e)) => match e.name().as_ref() {
 22	                b"kernel" => {
 23	                    for attr in e.attributes().flatten() {
 24	                        if attr.key.as_ref() == b"name" {
 25	                            top_name = String::from_utf8_lossy(&attr.value).into_owned();
 26	                        }
 27	                    }
 28	                }
 29	                b"port" => {
 30	                    let mut port_name = String::new();
 31	                    let mut mode = String::new();
 32	                    let mut data_width = 32u32;
 33	                    for attr in e.attributes().flatten() {
 34	                        let v = String::from_utf8_lossy(&attr.value).into_owned();
 35	                        match attr.key.as_ref() {
 36	                            b"name" => port_name = v,
 37	                            b"mode" => mode = v,
 38	                            b"dataWidth" => data_width = v.parse().unwrap_or(32),
 39	                            _ => {}
 40	                        }
 41	                    }
 42	                    if !port_name.is_empty() {
 43	                        port_info.insert(port_name, (mode, data_width));
 44	                    }
 45	                }
 46	                b"arg" => {
 47	                    let mut name = String::new();
 48	                    let mut id = 0u32;
 49	                    let mut qualifier = 0u32;
 50	                    let mut data_width = 32u32;
 51	                    let mut addr_width = 64u32;
 52	                    let mut depth = 16u32;
 53	                    let mut port = String::new();
 54	                    let mut scalar_width = None;
 55	
 56	                    for attr in e.attributes().flatten() {
 57	                        let v = String::from_utf8_lossy(&attr.value).into_owned();
 58	                        match attr.key.as_ref() {
 59	                            b"name" => name = v,
 60	                            b"id" => id = v.parse().unwrap_or(0),
 61	                            b"addressQualifier" => qualifier = v.parse().unwrap_or(0),
 62	                            b"dataWidth" => data_width = v.parse().unwrap_or(32),
 63	                            b"addrWidth" => addr_width = v.parse().unwrap_or(64),
 64	                            b"depth" => depth = v.parse().unwrap_or(16),
 65	                            b"port" => port = v,
 66	                            b"width" => scalar_width = Some(v.parse().unwrap_or(32)),
 67	                            _ => {}
 68	                        }
 69	                    }
 70	
 71	                    let kind = match qualifier {
 72	                        0 => ArgKind::Scalar {
 73	                            width: scalar_width.unwrap_or(data_width),
 74	                        },
 75	                        1 => {
 76	                            // Use dataWidth from the corresponding <port> element when
 77	                            // available. Mmap port widths are recorded on
 78	                            // <port name="m_axi_<name>"> rather than <arg>.
 79	                            let resolved_width =
 80	                                port_info.get(&port).map_or(data_width, |(_, w)| *w);
 81	                            ArgKind::Mmap {
 82	                                data_width: resolved_width,
 83	                                addr_width,
 84	                            }
 85	                        }
 86	                        4 => {
 87	                            // Determine direction from the <port mode="read_only|write_only">
 88	                            // attribute.  TAPA sets port names to the bare arg name (e.g. "a"),
 89	                            // so the old s_axis/istream heuristic fails; fall back to it only
 90	                            // when no <port> entry is found (non-TAPA XO files).
 91	                            let dir = if let Some((mode, _)) = port_info.get(&port) {
 92	                                match mode.as_str() {
 93	                                    "read_only" => StreamDir::In,
 94	                                    "write_only" => StreamDir::Out,
 95	                                    _ => fallback_stream_dir(&port),
 96	                                }
 97	                            } else {
 98	                                fallback_stream_dir(&port)
 99	                            };
100	                            // Use dataWidth from <port> when available.
101	                            let resolved_width =
102	                                port_info.get(&port).map_or(data_width, |(_, w)| *w);
103	                            ArgKind::Stream {
104	                                width: resolved_width,
105	                                depth,
106	                                dir,
107	                                protocol: StreamProtocol::Axis,
108	                            }
109	                        }
110	                        q => {
111	                            return Err(CosimError::Metadata(format!(
112	                                "unknown addressQualifier {q} for arg {name}"
113	                            )));
114	                        }
115	                    };
116	                    args.push(ArgSpec { name, id, kind });
117	                }
118	                _ => {}
119	            },
120	            Ok(Event::Eof) => break,
121	            Err(e) => return Err(CosimError::Metadata(e.to_string())),
122	            _ => {}
123	        }
124	        buf.clear();
125	    }
126	
127	    if top_name.is_empty() {
128	        return Err(CosimError::Metadata(
129	            "no kernel name found in kernel.xml".into(),
130	        ));
131	    }
132	
133	    Ok(KernelSpec {
134	        top_name,
135	        mode: Mode::Vitis,
136	        args,
137	        part_num: None,
138	        verilog_files: vec![],
139	        tcl_files: vec![],
140	        xci_files: vec![],
141	        scalar_register_map: HashMap::new(),
142	    })
143	}
144	
145	/// Heuristic stream direction for non-TAPA XO files that do not have a
146	/// <port mode="read_only|write_only"> element (e.g. hand-crafted kernels).
147	fn fallback_stream_dir(port: &str) -> StreamDir {
148	    if port.starts_with("s_axis") || port.contains("istream") {
149	        StreamDir::In
150	    } else {
151	        StreamDir::Out
152	    }
153	}

