 22	#[derive(Debug, Clone, PartialEq, Eq)]
 23	pub enum StreamProtocol {
 24	    Axis,
 25	    ApFifo,
 26	}
 27	
 28	#[derive(Debug, Clone, PartialEq, Eq)]
 29	pub enum ArgKind {
 30	    Scalar {
 31	        width: u32,
 32	    },
 33	    Mmap {
 34	        data_width: u32,
 35	        addr_width: u32,
 36	    },
 37	    Stream {
 38	        width: u32,
 39	        depth: u32,
 40	        dir: StreamDir,
 41	        protocol: StreamProtocol,
 42	    },
 43	}
 44	
 45	#[derive(Debug, Clone, PartialEq, Eq)]
 46	pub struct ArgSpec {
 47	    pub name: String,
 48	    pub id: u32,
 49	    pub kind: ArgKind,
 50	}
 51	
 52	#[derive(Debug, Clone)]
 53	pub struct KernelSpec {
 54	    pub top_name: String,
 55	    pub mode: Mode,
 56	    pub args: Vec<ArgSpec>,
 57	    pub part_num: Option<String>,
 58	    pub verilog_files: Vec<PathBuf>,
 59	    pub tcl_files: Vec<PathBuf>,
 60	    pub xci_files: Vec<PathBuf>,
 61	    pub scalar_register_map: HashMap<String, u32>,
 62	}
 63	
 64	pub fn load_spec(path: &Path) -> Result<(KernelSpec, tempfile::TempDir)> {
 65	    let file = std::fs::File::open(path)?;
 66	    let reader = std::io::BufReader::new(file);
 67	    let mut zip = zip::ZipArchive::new(reader).map_err(|e| CosimError::Metadata(e.to_string()))?;
 68	
 69	    match path.extension().and_then(|e| e.to_str()) {
 70	        Some("xo") => load_xo_spec(&mut zip, path),
 71	        Some("zip") => load_zip_spec(&mut zip, path),
 72	        other => Err(CosimError::Metadata(format!(
 73	            "unsupported cosim package extension: {other:?}"
 74	        ))),
 75	    }
 76	}
 77	
 78	fn load_xo_spec<R: Read + std::io::Seek>(
 79	    zip: &mut zip::ZipArchive<R>,
 80	    src: &Path,
 81	) -> Result<(KernelSpec, tempfile::TempDir)> {
 82	    let mut kernel_xml = None;
 83	    let mut scalar_register_map = HashMap::new();
 84	    let mut files = ExtractedFiles::default();
 85	
 86	    let extract_dir = make_extract_dir("xo")?;
 87	    for i in 0..zip.len() {
 88	        let mut file = zip
 89	            .by_index(i)
 90	            .map_err(|e| CosimError::Metadata(e.to_string()))?;
 91	        let name = file.name().to_owned();
 92	        if name.ends_with('/') {
 93	            continue;
 94	        }
 95	        let path = extract_file(&mut file, &name, extract_dir.path())?;
 96	        if name.ends_with("kernel.xml") {
 97	            kernel_xml = Some(std::fs::read_to_string(&path)?);
 98	            continue;
 99	        }
