118	/// Load a `tapa pack` HLS archive.
119	///
120	/// The archive carries exactly one metadata entry — `tapa.json`, the
121	/// verbatim copy of the work-directory state file — which strict-parses back
122	/// into [`tapa_ir::WorkState`]: the same types `tapa pack` wrote it from.
123	fn load_zip_spec<R: Read + std::io::Seek>(
124	    zip: &mut zip::ZipArchive<R>,
125	    src: &Path,
126	) -> Result<(KernelSpec, tempfile::TempDir)> {
127	    let mut state_json = None;
128	    let extract_dir = make_extract_dir("zip")?;
129	    let mut files = ExtractedFiles::default();
130	
131	    for i in 0..zip.len() {
132	        let mut file = zip
133	            .by_index(i)
134	            .map_err(|e| CosimError::Metadata(e.to_string()))?;
135	        let name = file.name().to_owned();
136	        if name.ends_with('/') {
137	            continue;
138	        }
139	        let path = extract_file(&mut file, &name, extract_dir.path())?;
140	        if name.ends_with(tapa_ir::work_state::FILE_NAME) {
141	            state_json = Some(std::fs::read_to_string(&path)?);
142	            continue;
143	        }
144	        files.classify(&name, path);
145	    }
146	
147	    let json = state_json.ok_or_else(|| {
148	        CosimError::Metadata(format!(
149	            "no {} in {}",
150	            tapa_ir::work_state::FILE_NAME,
151	            src.display(),
152	        ))
153	    })?;
154	    let state =
155	        tapa_ir::WorkState::from_json(&json).map_err(|e| CosimError::Metadata(e.to_string()))?;
156	    let mut spec = zip_pkg::spec_from_task_graph(&state.graph)?;
157	    spec.part_num = state.flow.part_num;
158	    spec.verilog_files = files.verilog;
159	    spec.tcl_files = files.tcl;
160	    spec.xci_files = files.xci;
