170	/// Returns true if the zip entry path has more than 2 directory components.
171	/// Only files at depth 0 or 1 are collected. Deeply nested files (e.g. inside
172	/// `ip_repo`/subdirectories) are not included.
173	fn is_deeply_nested(zip_name: &str) -> bool {
174	    zip_name.matches('/').count() > 2
175	}
