177	#[derive(Default)]
178	struct ExtractedFiles {
179	    verilog: Vec<PathBuf>,
180	    tcl: Vec<PathBuf>,
181	    xci: Vec<PathBuf>,
182	}
183	
184	impl ExtractedFiles {
185	    fn classify(&mut self, name: &str, path: PathBuf) {
186	        if has_ext(name, &["v", "sv", "vh", "dat"]) {
187	            self.verilog.push(path.clone());
188	        }
189	        if has_ext(name, &["tcl"]) {
190	            self.tcl.push(path.clone());
191	        }
192	        if has_ext(name, &["xci"]) && !is_deeply_nested(name) {
193	            self.xci.push(path);
194	        }
195	    }
196	}
197	
198	fn has_ext(name: &str, exts: &[&str]) -> bool {
199	    let ext = std::path::Path::new(name)
200	        .extension()
201	        .and_then(|e| e.to_str())
202	        .unwrap_or("");
203	    exts.iter().any(|x| ext.eq_ignore_ascii_case(x))
204	}
205	
206	fn extract_file(file: &mut zip::read::ZipFile<'_>, name: &str, out_dir: &Path) -> Result<PathBuf> {
207	    let rel = Path::new(name);
208	    let out = out_dir.join(rel);
209	    if let Some(parent) = out.parent() {
210	        std::fs::create_dir_all(parent)?;
211	    }
212	    let mut fp = std::fs::File::create(&out)?;
213	    std::io::copy(file, &mut fp)?;
214	    Ok(out)
215	}

