247	fn sv_literal(width_bits: u32, bytes_le: &[u8]) -> String {
248	    use std::fmt::Write;
249	    let width = width_bits.max(1);
250	    let hex = bytes_le.iter().rev().fold(String::new(), |mut acc, b| {
251	        let _ = write!(acc, "{b:02x}");
252	        acc
253	    });
254	    format!("{width}'h{hex}")
255	}
