257	/// Detect the AXI ID width for a given mmap port by scanning the Verilog
258	/// source files for the ARID port declaration.  Returns the bit-width
259	/// (e.g. 3 for `[2:0]`).  Defaults to 1 if the port is not found.
260	fn detect_axi_id_width(verilog_contents: &[String], mmap_name: &str) -> usize {
261	    let escaped = escape_verilog_identifier(&format!("m_axi_{mmap_name}_ARID"));
262	    // Match patterns like:  output [2:0] m_axi_foo_ARID  or  wire [2:0] ...
263	    // The left bound N in [N:0] gives width = N+1.
264	    let pattern = format!(
265	        r"\[\s*(\d+)\s*:\s*0\s*\]\s*{}",
266	        regex_lite::escape(&escaped)
267	    );
268	    let re = regex_lite::Regex::new(&pattern).unwrap();
269	    for text in verilog_contents {
270	        if let Some(caps) = re.captures(text) {
271	            if let Ok(n) = caps[1].parse::<usize>() {
272	                return n + 1;
273	            }
274	        }
275	    }
276	    1
277	}
