  1	use super::{ArgKind, ArgSpec, KernelSpec, Mode, StreamDir, StreamProtocol};
  2	use crate::error::{CosimError, Result};
  3	use std::collections::HashMap;
  4	use tapa_ir::port::{sanitize_array_name, ArgCategory, Port};
  5	use tapa_ir::TaskGraph;
  6	
  7	/// FIFO depth assumed for every stream argument the archive declares.
  8	///
  9	/// The archive carries no per-port depth: [`tapa_ir::Port`] has no such
 10	/// field, and the archive is written straight from that type. The previous
 11	/// untyped reader looked for a `depth` key and, for exactly that reason,
 12	/// always fell back to this value — so hardcoding it here preserves the
 13	/// argument shape bit for bit.
 14	const STREAM_DEPTH: u32 = 16;
 15	
 16	/// Address width assumed for every mmap argument the archive declares.
 17	/// Same story as [`STREAM_DEPTH`]: not in the schema, always defaulted.
 18	const MMAP_ADDR_WIDTH: u32 = 64;
 19	
 20	/// Project the packed task graph into the flat kernel argument list.
 21	///
 22	/// The top task's `ports` expand into one or more kernel arguments each,
 23	/// numbered in declaration order — that numbering is the kernel ABI the
 24	/// simulator binds against, so the order here is load-bearing.
 25	pub fn spec_from_task_graph(graph: &TaskGraph) -> Result<KernelSpec> {
 26	    let top_task = graph.tasks.get(&graph.top).ok_or_else(|| {
 27	        CosimError::Metadata(format!("top task '{}' missing from tasks", graph.top))
 28	    })?;
 29	
 30	    let mut args = Vec::new();
 31	    let mut next_id = 0u32;
 32	    for port in &top_task.ports {
 33	        // The frontend spells an array interface's channels `name[i]`, but
 34	        // every RTL identifier collapses that to `name_i` -- and these names
 35	        // are what the testbench binds ports, buffers and offset registers
 36	        // by, so they have to be the RTL spelling, not the schema spelling.
 37	        let name = sanitize_array_name(&port.name);
 38	        let name = name.as_str();
 39	        let width = port.width;
 40	        let chan_count = port.chan_count.unwrap_or(1);
 41	
 42	        match port.cat {
 43	            ArgCategory::Scalar => {
 44	                args.push(ArgSpec {
 45	                    name: name.to_owned(),
 46	                    id: next_id,
 47	                    kind: ArgKind::Scalar { width },
 48	                });
 49	                next_id += 1;
 50	            }
 51	            // `is_mmap_like` deliberately not used: it also covers `immap` /
 52	            // `ommap`, which this reader has never accepted (see below).
 53	            ArgCategory::Mmap | ArgCategory::AsyncMmap => {
 54	                let kind = ArgKind::Mmap {
 55	                    data_width: width,
 56	                    addr_width: MMAP_ADDR_WIDTH,
 57	                };
 58	                // `chan_count` is what makes an mmap port an `hmap`: the
 59	                // frontend fills it in for `hmap` and nothing else, so a plain
 60	                // mmap always leaves it unset (a `Some(1)` hmap is still an
 61	                // hmap). An `hmap<T, N, S>` is one host buffer that the host
 62	                // splits into N kernel m_axi arguments named `{name}_{i}` --
 63	                // the same fan-out `tapa pack` projects into `kernel.xml` and
 64	                // `tapa-codegen` wires to the AXI crossbar. Binding one
 65	                // argument here would bind the wrong ports *and* shift every
 66	                // later argument's id.
 67	                if let Some(hmap_chans) = port.chan_count {
 68	                    if hmap_chans == 0 {
 69	                        return Err(CosimError::Metadata(format!(
 70	                            "hmap channel count is 0 for argument '{name}'"
 71	                        )));
 72	                    }
 73	                    for i in 0..hmap_chans {
 74	                        args.push(ArgSpec {
 75	                            name: format!("{name}_{i}"),
 76	                            id: next_id,
 77	                            kind: kind.clone(),
 78	                        });
 79	                        next_id += 1;
 80	                    }
 81	                } else {
 82	                    args.push(ArgSpec {
 83	                        name: name.to_owned(),
 84	                        id: next_id,
 85	                        kind,
 86	                    });
 87	                    next_id += 1;
 88	                }
 89	            }
 90	            ArgCategory::Istream | ArgCategory::Ostream => {
 91	                args.push(ArgSpec {
 92	                    name: format!("{name}_s"),
 93	                    id: next_id,
 94	                    kind: ArgKind::Stream {
 95	                        width,
 96	                        depth: STREAM_DEPTH,
 97	                        dir: stream_dir(port),
 98	                        protocol: StreamProtocol::ApFifo,
 99	                    },
100	                });
101	                next_id += 1;
102	            }
103	            ArgCategory::Istreams | ArgCategory::Ostreams => {
104	                for i in 0..chan_count {
105	                    args.push(ArgSpec {
106	                        name: format!("{name}_{i}"),
107	                        id: next_id,
108	                        kind: ArgKind::Stream {
109	                            width,
110	                            depth: STREAM_DEPTH,
111	                            dir: stream_dir(port),
112	                            protocol: StreamProtocol::ApFifo,
113	                        },
114	                    });
115	                    next_id += 1;
116	                }
117	            }
118	            // Read-only / write-only mmaps have never been wired up here.
119	            // Rejecting them keeps that an explicit, loud limitation rather
120	            // than silently binding them as plain mmaps.
121	            ArgCategory::Immap | ArgCategory::Ommap => {
122	                return Err(CosimError::Metadata(format!(
123	                    "unsupported port category '{}'",
124	                    port.cat.as_str()
125	                )));
126	            }
127	        }
128	    }
129	
130	    Ok(KernelSpec {
131	        top_name: graph.top.clone(),
132	        mode: Mode::Hls,
133	        args,
134	        // Recovered by the caller from the state file's flow settings, the
135	        // one place the resolved part number is written.
136	        part_num: None,
137	        verilog_files: vec![],
138	        tcl_files: vec![],
139	        xci_files: vec![],
140	        scalar_register_map: HashMap::new(),
141	    })
142	}
143	
144	/// Direction of a stream port, from its category.
145	fn stream_dir(port: &Port) -> StreamDir {
146	    if port.cat.is_output_stream() {
147	        StreamDir::Out
148	    } else {
149	        StreamDir::In
150	    }
151	}

