  1	pub fn escape_verilog_identifier(name: &str) -> String {
  2	    if is_bare_verilog_identifier(name) {
  3	        return name.to_owned();
  4	    }
  5	    format!("\\{name} ")
  6	}
  7	
  8	pub fn verilator_identifier(name: &str) -> String {
  9	    use std::fmt::Write;
 10	    let mut out = String::with_capacity(name.len());
 11	    for ch in name.chars() {
 12	        if ch.is_ascii_alphanumeric() || ch == '_' {
 13	            out.push(ch);
 14	        } else {
 15	            let _ = write!(out, "__{:03x}", ch as u32);
 16	        }
 17	    }
 18	    if out.is_empty() {
 19	        out.push('_');
 20	    }
 21	    if out.chars().next().is_some_and(|c| c.is_ascii_digit()) {
 22	        out.insert(0, '_');
 23	    }
 24	    out
 25	}
 26	
 27	pub fn cpp_identifier(name: &str) -> String {
 28	    let mut out = String::with_capacity(name.len());
 29	    for ch in name.chars() {
 30	        if ch.is_ascii_alphanumeric() || ch == '_' {
 31	            out.push(ch);
 32	        } else if ch == '[' {
 33	            out.push('_');
 34	        } else if ch == ']' {
 35	            // skip closing bracket
 36	        } else {
 37	            out.push('_');
 38	        }
 39	    }
 40	    if out.is_empty() {
 41	        out.push('_');
 42	    }
 43	    if out.chars().next().is_some_and(|c| c.is_ascii_digit()) {
 44	        out.insert(0, '_');
 45	    }
 46	    out
 47	}
