 57	pub fn infer_peek_name(stream_name: &str) -> Option<String> {
 58	    if let Some(base) = stream_name.strip_suffix("_s") {
 59	        return Some(format!("{base}_peek"));
 60	    }
 61	    let mut iter = stream_name.rsplitn(2, '_');
 62	    if let (Some(suffix), Some(base)) = (iter.next(), iter.next()) {
 63	        if suffix.chars().all(|c| c.is_ascii_digit()) {
 64	            return Some(format!("{base}_peek_{suffix}"));
 65	        }
 66	    }
 67	    Some(format!("{stream_name}_peek"))
 68	}
