 94	fn is_bare_verilog_identifier(name: &str) -> bool {
 95	    let mut chars = name.chars();
 96	    let Some(first) = chars.next() else {
 97	        return false;
 98	    };
 99	    (first.is_ascii_alphabetic() || first == '_')
100	        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
101	}
