 70	pub fn stream_peek_ports_exist(
 71	    verilog_contents: &[String],
 72	    top_name: &str,
 73	    peek_name: &str,
 74	) -> bool {
 75	    let dout_port = format!("{peek_name}_dout");
 76	    let empty_n_port = format!("{peek_name}_empty_n");
 77	    let module_decl = format!("module {top_name}");
 78	    verilog_contents.iter().any(|text| {
 79	        if !text.contains(&module_decl) {
 80	            return false;
 81	        }
 82	        let has_dout = text.lines().any(|line| {
 83	            let t = line.trim();
 84	            (t.starts_with("input") || t.starts_with("output")) && t.contains(&dout_port)
 85	        });
 86	        let has_empty_n = text.lines().any(|line| {
 87	            let t = line.trim();
 88	            (t.starts_with("input") || t.starts_with("output")) && t.contains(&empty_n_port)
 89	        });
 90	        has_dout && has_empty_n
 91	    })
 92	}
